1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	let pendingMessages = new Map();
24	let controlWs = null;
25	let reconnectTimer = null;
26	let reconnectAttempts = 0;
27	
28	// ===== sessionStorage：刷新后记住连接状态 =====
29	const SS_PREFIX = 'lanchat_conn_';
30	
31	function markConnected(uuid) {
32	    try { sessionStorage.setItem(SS_PREFIX + uuid, '1'); } catch (e) { /* ignore */ }
33	}
34	
35	function markDisconnected(uuid) {
36	    try { sessionStorage.removeItem(SS_PREFIX + uuid); } catch (e) { /* ignore */ }
37	}
38	
39	function getStoredConnectedPeers() {
40	    const peers = [];
41	    try {
42	        for (let i = 0; i < sessionStorage.length; i++) {
43	            const key = sessionStorage.key(i);
44	            if (key && key.startsWith(SS_PREFIX)) {
45	                peers.push(key.slice(SS_PREFIX.length));
46	            }
47	        }
48	    } catch (e) { /* ignore */ }
49	    return peers;
50	}
51	
52	// 文件传输状态
53	let pendingFileTransfers = {};
54	
55	// ===== DOM 引用 =====
56	const $ = (id) => document.getElementById(id);
57	const onlineList = $('online-list');
58	const onlineCount = $('online-count');
59	const pendingList = $('pending-list');
60	const pendingCount = $('pending-count');
61	const panelPending = $('panel-pending');
62	const contactsList = $('contacts-list');
63	const contactsCount = $('contacts-count');
64	const chatPlaceholder = $('chat-placeholder');
65	const chatContainer = $('chat-container');
66	const chatPeerName = $('chat-peer-name');
67	const chatPeerStatus = $('chat-peer-status');
68	const chatConnectBar = $('chat-connect-bar');
69	const btnChatConnect = $('btn-chat-connect');
70	const chatMessages = $('chat-messages');
71	const msgInput = $('msg-input');
72	const btnSend = $('btn-send');
73	const btnSendFile = $('btn-send-file');
74	const fileInput = $('file-input');
75	const btnCloseChat = $('btn-close-chat');
76	const btnDeleteContact = $('btn-delete-contact');
77	const btnDisconnect = $('btn-disconnect');
78	const btnScan = $('btn-scan');
79	const btnEditName = $('btn-edit-name');
80	const modalOverlay = $('modal-overlay');
81	const modalNameInput = $('modal-name-input');
82	const fileModalOverlay = $('file-modal-overlay');
83	const fileModalTitle = $('file-modal-title');
84	const fileModalBody = $('file-modal-body');
85	const fileModalButtons = $('file-modal-buttons');
86	
87	// ===== 初始化 =====
88	async function init() {
89	    await connectControl();
90	    bindEvents();
91	    startPolling();
92	}
93	
94	/** 连接控制 WebSocket */
95	async function connectControl() {
96	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
97	    const url = `${protocol}//${location.host}/ws/control`;
98	
99	    return new Promise((resolve) => {
100	        controlWs = new WebSocket(url);
101	
102	        controlWs.onopen = () => {
103	            reconnectAttempts = 0;
104	            console.log('[Control] 已连接');
105	        };
106	
107	        controlWs.onmessage = (e) => {
108	            const msg = JSON.parse(e.data);
109	            handleControlMessage(msg);
110	            if (msg.type === 'init') resolve();
111	        };
112	
113	        controlWs.onclose = () => {
114	            console.log('[Control] 断开，尝试重连...');
115	            scheduleReconnect();
116	        };
117	
118	        controlWs.onerror = () => {};
119	    });
120	}
121	
122	/** 控制 WS 断开后指数退避重连 */
123	function scheduleReconnect() {
124	    if (reconnectTimer) return;
125	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
126	    const jitter = delay * (0.8 + Math.random() * 0.4);
127	    reconnectAttempts++;
128	    reconnectTimer = setTimeout(async () => {
129	        reconnectTimer = null;
130	        await connectControl();
131	    }, jitter);
132	}
133	
134	// ===== 事件绑定 =====
135	function bindEvents() {
136	    btnScan.addEventListener('click', () => fetchPeers());
137	    btnEditName.addEventListener('click', showEditNameModal);
138	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
139	    $('btn-modal-save').addEventListener('click', saveName);
140	    modalNameInput.addEventListener('keydown', (e) => {
141	        if (e.key === 'Enter') saveName();
142	    });
143	    btnSend.addEventListener('click', sendCurrentMessage);
144	    msgInput.addEventListener('keydown', (e) => {
145	        if (e.key === 'Enter') sendCurrentMessage();
146	    });
147	    btnSendFile.addEventListener('click', () => fileInput.click());
148	    fileInput.addEventListener('change', onFileSelected);
149	    btnCloseChat.addEventListener('click', closeCurrentChat);
150	    btnDisconnect.addEventListener('click', disconnectCurrentChat);
151	    btnChatConnect.addEventListener('click', () => {
152	        if (!currentChat) return;
153	        const peer = onlinePeers.get(currentChat) || contacts.get(currentChat);
154	        if (peer) connectToPeer(currentChat, peer.name, peer.ip);
155	    });
156	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
157	
158	    // 手动连接：toggle 展开/收起
159	    const btnManualConnect = $('btn-manual-connect');
160	    const manualIpInput = $('manual-ip-input');
161	
162	    btnManualConnect.addEventListener('click', () => {
163	        const raw = manualIpInput.value.trim();
164	        if (!raw) return;
165	        let [ip, port] = raw.split(':');
166	        port = parseInt(port) || 50002;
167	        connectByIp(ip, port);
168	        manualIpInput.value = '';
169	        toggleManualConnect(); // 收起
170	    });
171	    manualIpInput.addEventListener('keydown', (e) => {
172	        if (e.key === 'Enter') btnManualConnect.click();
173	    });
174	
175	    // 文件续传按钮（事件委托）
176	    chatMessages.addEventListener('click', (e) => {
177	        const btn = e.target.closest('.btn-retry-file');
178	        if (btn) {
179	            const transferId = btn.dataset.transferId;
180	            if (transferId) retryFileTransfer(transferId);
181	        }
182	    });
183	}
184	
185	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
186	function toggleManualConnect() {
187	    const row = $('manual-connect-row');
188	    const btn = $('btn-toggle-manual');
189	    if (!row || !btn) return;
190	    const visible = row.style.display !== 'none';
191	    row.style.display = visible ? 'none' : '';
192	    btn.textContent = visible ? '➕' : '✖';
193	    if (!visible) $('manual-ip-input').focus();
194	}
195	
196	// ===== 定时轮询 =====
197	function startPolling() {
198	    setInterval(fetchPeers, 3000);
199	    setInterval(fetchContacts, 5000);
200	    fetchPeers();
201	    fetchContacts();
202	}
203	
204	async function fetchPeers() {
205	    try {
206	        const resp = await fetch('/api/peers');
207	        const peers = await resp.json();
208	        updateOnlinePeers(peers);
209	    } catch (e) { /* ignore */ }
210	}
211	
212	async function fetchContacts() {
213	    try {
214	        const resp = await fetch('/api/contacts');
215	        const list = await resp.json();
216	        updateContacts(list);
217	    } catch (e) { /* ignore */ }
218	}
219	
220	// ===== 控制消息处理 =====
221	function handleControlMessage(msg) {
222	    const handlers = {
223	        init: handleInit,
224	        peer_online: handlePeerOnline,
225	        peer_offline: handlePeerOffline,
226	        incoming_connection: handleIncomingConnection,
227	        pending_update: handlePendingUpdate,
228	        connection_established: handleConnectionEstablished,
229	        peer_disconnected: handlePeerDisconnected,
230	        disconnected: handleDisconnected,
231	        chat_message: handleIncomingMessage,
232	        message_ack: handleMessageAck,
233	        send_failed: handleSendFailed,
234	        incoming_file_request: handleIncomingFileRequest,
235	        file_request_response: handleFileRequestResponseFromControl,
236	        forward_file_response: handleForwardFileResponse,
237	        transfer_progress: handleTransferProgress,
238	        transfer_complete: handleTransferComplete,
239	        transfer_cancelled: handleTransferCancelled,
240	        transfer_resumed: handleTransferResumed,
241	    };
242	    const handler = handlers[msg.type];
243	    if (handler) handler(msg);
244	}
245	
246	function handleInit(msg) {
247	    myInfo = msg;
248	    $('my-name-label').textContent = msg.name;
249	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
250	    $('my-network-label').textContent = `网段: ${msg.network}`;
251	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
252	
253	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
254	    if (msg.online_peers && msg.online_peers.length > 0) {
255	        updateOnlinePeers(msg.online_peers);
256	    }
257	
258	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
259	    if (msg.contacts && msg.contacts.length > 0) {
260	        updateContacts(msg.contacts);
261	    }
262	
263	    // 步骤3：自动重连刷新前已建立的连接（双重来源）
264	    //   来源A — sessionStorage：本浏览器侧记忆，刷新不丢失
265	    //   来源B — active_peers：后端记录，对端浏览器仍连着本后端的 chat WS
266	    const toReconnect = new Set();
267	    for (const uuid of getStoredConnectedPeers()) {
268	        toReconnect.add(uuid);
269	    }
270	    if (msg.active_peers && msg.active_peers.length > 0) {
271	        for (const uuid of msg.active_peers) {
272	            toReconnect.add(uuid);
273	        }
274	    }
275	    for (const peerUuid of toReconnect) {
276	        autoReconnect(peerUuid);
277	    }
278	}
279	
280	function handlePeerOnline(msg) {
281	    // 过滤自己
282	    if (msg.uuid === myInfo.uuid) return;
283	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
284	    // 如果历史联系人里有，更新在线状态
285	    if (contacts.has(msg.uuid)) {
286	        contacts.get(msg.uuid).status = 'online';
287	    }
288	    renderOnlineList();
289	    renderContactsList();
290	    updateChatHeaderStatus();
291	}
292	
293	function handlePeerOffline(msg) {
294	    onlinePeers.delete(msg.uuid);
295	    if (contacts.has(msg.uuid)) {
296	        contacts.get(msg.uuid).status = 'offline';
297	    }
298	    // 对应聊天 WS 断开
299	    const ws = activeChats.get(msg.uuid);
300	    if (ws) {
301	        ws.close();
302	        activeChats.delete(msg.uuid);
303	    }
304	    renderOnlineList();
305	    renderContactsList();
306	    updateChatHeaderStatus();
307	    addSystemMessage(msg.uuid, `${msg.name} 已下线`);
308	}
309	
310	function handleIncomingConnection(msg) {
311	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
312	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
313	    renderPendingList();
314	}
315	
316	function handlePendingUpdate(msg) {
317	    // count 可能在 pending 列表被其他地方修改后推送
318	    if (msg.count === 0) pendingRequests.clear();
319	}
320	
321	function handleConnectionEstablished(msg) {
322	    pendingRequests.delete(msg.uuid);
323	    connectedPeers.add(msg.uuid);  // 接收方也标记为已连接
324	    markConnected(msg.uuid);
325	    // 只在 contacts 中不存在时才新建，否则保留已有消息（避免覆盖聊天记录）
326	    if (!contacts.has(msg.uuid)) {
327	        contacts.set(msg.uuid, {
328	            name: msg.name,
329	            ip: msg.ip,
330	            status: 'online',
331	            messages: [],
332	        });
333	    } else {
334	        const c = contacts.get(msg.uuid);
335	        c.name = msg.name;
336	        c.ip = msg.ip;
337	        c.status = 'online';
338	    }
339	    renderPendingList();
340	    renderOnlineList();
341	    renderContactsList();
342	    updateChatHeaderStatus();
343	    // 如果正在等对方的确认（主动发起方），打开聊天
344	    if (currentChat === msg.uuid || !currentChat) {
345	        openChat(msg.uuid);
346	    }
347	}
348	
349	function handlePeerDisconnected(msg) {
350	    activeChats.delete(msg.uuid);
351	    connectedPeers.delete(msg.uuid);
352	    markDisconnected(msg.uuid);
353	    pendingRequests.delete(msg.uuid);
354	    // 中止与该对端的所有进行中文件上传
355	    abortTransfersForPeer(msg.uuid);
356	    renderPendingList();
357	    renderOnlineList();
358	    renderContactsList();
359	    if (currentChat === msg.uuid) {
360	        updateChatHeaderStatus();
361	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
362	    }
363	}
364	
365	/** 自己主动断开后的确认回调（后端关闭对端 WS 后返回） */
366	function handleDisconnected(msg) {
367	    activeChats.delete(msg.uuid);
368	    connectedPeers.delete(msg.uuid);
369	    markDisconnected(msg.uuid);
370	    renderOnlineList();
371	    renderContactsList();
372	    if (currentChat === msg.uuid) {
373	        updateChatHeaderStatus();
374	        addSystemMessage(msg.uuid, '你已断开连接');
375	    }
376	}
377	
378	function handleIncomingMessage(msg) {
379	    const uuid = msg.from;
380	    // 保存消息到联系人内存
381	    if (!contacts.has(uuid)) {
382	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
383	    }
384	    const contact = contacts.get(uuid);
385	    contact.messages.push({
386	        from: uuid,
387	        content: msg.content,
388	        msg_id: msg.msg_id,
389	        timestamp: msg.timestamp,
390	    });
391	    // 立即通知后端持久化到 contacts.json（与后端 _relay_from_peer 形成双保险，
392	    // storage.append_message 内部有 msg_id 去重，重复调用安全）
393	    controlWs.send(JSON.stringify({
394	        type: 'save_message',
395	        peer_uuid: uuid,
396	        sender: uuid,
397	        content: msg.content,
398	        msg_id: msg.msg_id,
399	    }));
400	    if (currentChat === uuid) {
401	        renderMessages(uuid);
402	    }
403	    // 当前没有聊天窗口时，自动打开
404	    if (!currentChat) {
405	        openChat(uuid);
406	    }
407	    renderContactsList();
408	}
409	
410	function handleMessageAck(msg) {
411	    pendingMessages.delete(msg.msg_id);
412	    if (currentChat) renderMessages(currentChat);
413	}
414	
415	function handleSendFailed(msg) {
416	    // 标记消息发送失败
417	    const pending = pendingMessages.get(msg.msg_id);
418	    if (pending) {
419	        pending.status = 'failed';
420	        pendingMessages.set(msg.msg_id, pending);
421	    }
422	    if (currentChat) renderMessages(currentChat);
423	}
424	
425	// ===== 文件传输消息处理 =====
426	
427	function handleIncomingFileRequest(msg) {
428	    // 续传：自动接受，不弹窗
429	    if (msg.resume) {
430	        autoAcceptResumeTransfer(msg);
431	        return;
432	    }
433	    showFileRequestModal(msg);
434	}
435	
436	/** 续传自动接受（不弹窗），更新已有文件气泡或插入新气泡 */
437	function autoAcceptResumeTransfer(msg) {
438	    // 发送接受响应
439	    controlWs.send(JSON.stringify({
440	        type: 'file_response',
441	        transfer_id: msg.transfer_id,
442	        accepted: true,
443	    }));
444	
445	    const uuid = msg.from_uuid;
446	    if (!contacts.has(uuid)) {
447	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
448	    }
449	    const contact = contacts.get(uuid);
450	    const msgId = 'f_' + msg.transfer_id;
451	    const existingIdx = contact.messages.findIndex(m => m.msg_id === msgId);
452	    if (existingIdx >= 0) {
453	        // 续传：更新已有消息
454	        contact.messages[existingIdx].status = 'downloading';
455	        contact.messages[existingIdx].progress = 0;
456	        saveFileMessage(uuid, contact.messages[existingIdx]);
457	    } else {
458	        const fileMsg = {
459	            from: uuid,
460	            type: 'file',
461	            msg_id: msgId,
462	            timestamp: new Date().toISOString(),
463	            file_name: msg.file_name,
464	            file_size: msg.file_size,
465	            transfer_id: msg.transfer_id,
466	            direction: 'receive',
467	            status: 'downloading',
468	            progress: 0,
469	        };
470	        contact.messages.push(fileMsg);
471	        saveFileMessage(uuid, fileMsg);
472	    }
473	    if (currentChat === uuid) {
474	        renderMessages(uuid);
475	    } else {
476	        openChat(uuid);
477	    }
478	}
479	
480	/**
481	 * 处理来自控制 WS 的文件请求响应（通过后端 _relay_from_peer 转发的）。
482	 * 与来自聊天 WS 直连的响应统一走 handleFileRequestResponse。
483	 */
484	function handleFileRequestResponseFromControl(msg) {
485	    handleFileRequestResponse(msg);
486	}
487	
488	/**
489	 * 统一处理文件请求响应。
490	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
491	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
492	 */
493	function handleFileRequestResponse(msg) {
494	    const transferId = msg.transfer_id;
495	    const t = pendingFileTransfers[transferId];
496	    if (!t) return; // 不是我们的传输
497	
498	    if (msg.accepted) {
499	        if (t.started) return; // 已启动，幂等
500	        t.started = true;
501	        startChunkUpload(transferId);
502	    } else {
503	        // 对方拒绝
504	        delete pendingFileTransfers[transferId];
505	        const fileMsg = findFileMsgByTransferId(transferId);
506	        if (fileMsg) {
507	            fileMsg.status = 'failed';
508	            // 通过 transferId 找到对应的联系人 uuid
509	            saveFileMessage(t.uuid, fileMsg);
510	            if (currentChat) renderMessages(currentChat);
511	        }
512	        showToast('对方拒绝了文件传输');
513	    }
514	}
515	
516	function handleTransferProgress(msg) {
517	    // 接收方：更新文件消息进度
518	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
519	    if (fileMsg && msg.total_bytes > 0) {
520	        fileMsg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
521	        if (currentChat) renderMessages(currentChat);
522	    }
523	}
524	
525	function handleTransferComplete(msg) {
526	    // 接收方：传输完成
527	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
528	    if (fileMsg) {
529	        fileMsg.status = msg.verified ? 'complete' : 'failed';
530	        fileMsg.progress = 100;
531	        saveFileMessage(currentChat, fileMsg);
532	        if (currentChat) renderMessages(currentChat);
533	    }
534	    if (msg.verified) {
535	        showToast(`文件接收完成: ${msg.file_name}`);
536	    } else {
537	        showToast(`文件校验失败: ${msg.file_name}`);
538	    }
539	}
540	
541	function handleTransferCancelled(msg) {
542	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
543	    if (fileMsg) {
544	        fileMsg.status = 'cancelled';
545	        saveFileMessage(currentChat, fileMsg);
546	        if (currentChat) renderMessages(currentChat);
547	    }
548	    // 清理上传方状态
549	    if (pendingFileTransfers[msg.transfer_id]) {
550	        delete pendingFileTransfers[msg.transfer_id];
551	    }
552	    showToast('文件传输已取消');
553	}
554	
555	function handleTransferResumed(msg) {
556	    // 续传恢复通知 — 不做额外弹窗，进度条会在 transfer_progress 中更新
557	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
558	    if (fileMsg) {
559	        fileMsg.status = 'downloading';
560	        if (currentChat) renderMessages(currentChat);
561	    }
562	}
563	
564	/**
565	 * 当后端无法直接发送 file_response 给发送方时（发送方是被动接收方，无 incoming WS），
566	 * 后端通知本浏览器通过本方的 chat WS 转发响应给对端后端。
567	 */
568	function handleForwardFileResponse(msg) {
569	    const chatWs = activeChats.get(msg.to_uuid);
570	    if (chatWs && chatWs.readyState === WebSocket.OPEN) {
571	        chatWs.send(JSON.stringify({
572	            type: 'file_response',
573	            transfer_id: msg.transfer_id,
574	            accepted: msg.accepted,
575	        }));
576	    }
577	}
578	
579	// ===== 在线列表渲染 =====
580	function updateOnlinePeers(peers) {
581	    onlinePeers.clear();
582	    for (const p of peers) {
583	        // 过滤自己
584	        if (p.uuid === myInfo.uuid) continue;
