896	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
897	        const ws = new WebSocket(wsUrl);
898	
899	        ws.onopen = () => {
900	            // 发送连接请求，带上自己的 token 给对方后端验证
901	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
902	            ws.send(JSON.stringify({
903	                type: 'connect_request',
904	                uuid: myInfo.uuid,
905	                name: myInfo.name,
906	                token: myInfo.token,
907	                ip: myInfo.ip,
908	                ws_port: myInfo.ws_port,
