927	                    name: name,
928	                    ip: ip,
929	                    ws_port: peer.ws_port || 50002,
930	                }));
931	            } else if (msg.type === 'connect_rejected') {
932	                ws.close();
933	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
934	                addSystemMessage(uuid, reason);
935	                showToast(reason);
936	            }
937	        };
938	
939	        ws.onclose = () => {
940	            activeChats.delete(uuid);
941	            connectedPeers.delete(uuid);
942	            markDisconnected(uuid);
943	            // 中止与该对端的所有进行中文件上传（接收方断开时也要停止发送）
944	            abortTransfersForPeer(uuid);
