1098	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
1099	function setupPeerMessageHandler(uuid, ws) {
1100	    ws.onmessage = (e) => {
1101	        const msg = JSON.parse(e.data);
1102	        if (msg.type === 'chat') {
1103	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
1104	            handleDirectChatMessage(uuid, msg);
1105	        } else if (msg.type === 'file_request') {
1106	            // 对端后端通过 chat WS 发来的文件请求（HTTP relay 失败的 fallback）
1107	            // 先在自己后端注册 transfer，再弹窗确认
1108	            controlWs.send(JSON.stringify({
1109	                type: 'register_transfer',
1110	                transfer_id: msg.transfer_id,
1111	                file_name: msg.file_name,
1112	                file_size: msg.file_size,
1113	                chunk_size: msg.chunk_size,
1114	                total_chunks: msg.total_chunks,
1115	                from_uuid: uuid,
1116	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1117	            }));
1118	            // 用 from_uuid（chat WS 的对端 uuid）触发弹窗
1119	            showFileRequestModal({
1120	                transfer_id: msg.transfer_id,
1121	                file_name: msg.file_name,
1122	                file_size: msg.file_size,
1123	                from_uuid: uuid,
1124	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1125	            });
1126	        } else if (msg.type === 'file_response') {
1127	            // 对方对我方文件请求的响应
1128	            handleFileRequestResponse(msg);
1129	        } else if (msg.type === 'file_cancel') {
1130	            // 对方取消了传输
1131	            handleTransferCancelled(msg);
1132	        } else if (msg.type === 'ack') {
1133	            handleMessageAck(msg);
1134	        }
1135	    };
1136	}
