1536	        timestamp: new Date().toISOString(),
1537	        file_name: file.name,
1538	        file_size: file.size,
1539	        transfer_id: transferId,
1540	        direction: 'send',
1541	        status: 'waiting',
1542	        progress: 0,
1543	    };
1544	    contact.messages.push(fileMsg);
1545	    renderMessages(uuid);
1546	
1547	    // 持久化文件消息
1548	    saveFileMessage(uuid, fileMsg);
1549	
1550	    // 注册待处理传输
1551	    pendingFileTransfers[transferId] = {
1552	        file: file,
1553	        uuid: uuid,
1554	        totalChunks: totalChunks,
1555	        CHUNK_SIZE: CHUNK_SIZE,
1556	        transferId: transferId,
1557	        currentChunk: 0,
1558	        started: false,
1559	        aborted: false,
1560	    };
1561	
1562	    const fileRequestMsg = {
1563	        transfer_id: transferId,
1564	        file_name: file.name,
1565	        file_size: file.size,
1566	        chunk_size: CHUNK_SIZE,
1567	        total_chunks: totalChunks,
1568	        resume: false,
1569	    };
1570	
1571	    // 优先走直连 chat WS；没有则回退到 control WS 转发
1572	    const ws = activeChats.get(uuid);
1573	    if (ws && ws.readyState === WebSocket.OPEN) {
1574	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
1575	    } else {
1576	        // 回退路径：通过 control WS → 自己后端 → 转发给对端
