1585	/**
1586	 * 开始分片上传文件到对方后端。
1587	 * 每发送一个分片后更新聊天气泡中的进度。
1588	 */
1589	async function startChunkUpload(transferId) {
1590	    const t = pendingFileTransfers[transferId];
1591	    if (!t) return;
1592	
1593	    const fileMsg = findFileMsgByTransferId(transferId);
1594	    if (fileMsg) {
1595	        fileMsg.status = 'uploading';
1596	        saveFileMessage(t.uuid, fileMsg);
1597	        if (currentChat === t.uuid) renderMessages(t.uuid);
1598	    }
1599	
1600	    const peer = onlinePeers.get(t.uuid);
1601	    if (!peer) {
1602	        showToast('对方不在线，无法发送文件');
1603	        if (fileMsg) {
1604	            fileMsg.status = 'failed';
1605	            saveFileMessage(t.uuid, fileMsg);
1606	            if (currentChat === t.uuid) renderMessages(t.uuid);
1607	        }
1608	        delete pendingFileTransfers[transferId];
1609	        return;
1610	    }
1611	
1612	    const file = t.file;
1613	    const CHUNK_SIZE = t.CHUNK_SIZE;
1614	    const totalChunks = t.totalChunks;
1615	    const peerPort = peer.ws_port || 50002;
1616	
1617	    for (let i = t.currentChunk; i < totalChunks; i++) {
1618	        // 检查连接是否被中断（断开连接 / 对方下线）
1619	        if (t.aborted) {
1620	            if (fileMsg) {
1621	                fileMsg.status = 'cancelled';
1622	                saveFileMessage(t.uuid, fileMsg);
1623	                if (currentChat === t.uuid) renderMessages(t.uuid);
1624	            }
1625	            return; // 连接中断，中止上传
1626	        }
1627	
1628	        const start = i * CHUNK_SIZE;
1629	        const end = Math.min(start + CHUNK_SIZE, file.size);
1630	        const blob = file.slice(start, end);
1631	        const dataB64 = await readAsBase64(blob);
1632	
1633	        let retries = 0;
1634	        let success = false;
1635	
1636	        while (retries < 3 && !success) {
1637	            try {
1638	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1639	                    method: 'POST',
1640	                    headers: { 'Content-Type': 'application/json' },
1641	                    body: JSON.stringify({
1642	                        transfer_id: transferId,
1643	                        chunk_index: i,
1644	                        data: dataB64,
1645	                    }),
1646	                });
1647	                if (resp.ok) {
1648	                    success = true;
1649	                    t.currentChunk = i + 1;
1650	                    // 更新进度条
1651	                    if (fileMsg) {
1652	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1653	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1654	                    }
1655	                } else {
1656	                    retries++;
1657	                }
1658	            } catch (e) {
1659	                retries++;
1660	            }
1661	        }
1662	
1663	        if (!success) {
1664	            t.failed = true;
1665	            if (fileMsg) {
1666	                fileMsg.status = 'failed';
1667	                saveFileMessage(t.uuid, fileMsg);
1668	                if (currentChat === t.uuid) renderMessages(t.uuid);
1669	            }
1670	            return; // 传输中断（保留 t 以便续传）
1671	        }
1672	    }
1673	
1674	    // 所有分片发送完毕 → 通知对方合并
1675	    try {
1676	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1677	            method: 'POST',
1678	            headers: { 'Content-Type': 'application/json' },
1679	            body: JSON.stringify({ transfer_id: transferId }),
1680	        });
1681	        if (fileMsg) {
1682	            fileMsg.status = 'complete';
1683	            fileMsg.progress = 100;
1684	            saveFileMessage(t.uuid, fileMsg);
1685	            if (currentChat === t.uuid) renderMessages(t.uuid);
1686	        }
1687	    } catch (e) {
1688	        if (fileMsg) {
1689	            fileMsg.status = 'failed';
1690	            saveFileMessage(t.uuid, fileMsg);
1691	            if (currentChat === t.uuid) renderMessages(t.uuid);
1692	        }
1693	    }
1694	
1695	    delete pendingFileTransfers[transferId];
1696	}
