1698	/**
1699	 * 重新发送（续传）失败的文件。查询接收方已收分片，只补发缺失部分。
1700	 * @param {string} transferId - 原传输 ID
1701	 */
1702	async function retryFileTransfer(transferId) {
1703	    // 1. 检查是否有文件数据（页面刷新后 File 对象会丢失）
1704	    const t = pendingFileTransfers[transferId];
1705	    if (!t || !t.file) {
1706	        showToast('无法续传：文件数据已丢失，请重新选择文件发送');
1707	        return;
1708	    }
1709	
1710	    // 2. 检查对方是否在线
1711	    const peer = onlinePeers.get(t.uuid);
1712	    if (!peer) {
1713	        showToast('对方不在线，无法续传');
1714	        return;
1715	    }
1716	
1717	    // 2.5 必须有已建立的 chat WS 连接才能续传（否则 file_request 无法送达）
1718	    const chatWs = activeChats.get(t.uuid);
1719	    const isConnected = (chatWs && chatWs.readyState === WebSocket.OPEN) || connectedPeers.has(t.uuid);
1720	    if (!isConnected) {
1721	        showToast('请先点击"连接"建立聊天连接，再重新发送文件');
1722	        return;
1723	    }
1724	
1725	    // 3. 查询接收方已收到的分片数
1726	    let receivedChunks = 0;
1727	    const peerPort = peer.ws_port || 50002;
1728	    try {
1729	        const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/status/${transferId}`);
1730	        if (resp.ok) {
1731	            const status = await resp.json();
1732	            receivedChunks = status.received_chunks_count || 0;
1733	        }
1734	    } catch (e) {
1735	        // 进度丢失，从头开始
1736	        console.log('[Retry] 无法获取进度，从头开始:', e.message);
1737	    }
1738	
1739	    // 4. 更新传输状态 — 从已收到的下一片开始
1740	    t.currentChunk = receivedChunks;
1741	    t.started = false;
1742	    t.failed = false;
1743	    t.aborted = false;
1744	
1745	    // 5. 更新文件消息气泡
1746	    const fileMsg = findFileMsgByTransferId(transferId);
1747	    if (fileMsg) {
1748	        fileMsg.status = 'waiting';
1749	        fileMsg.progress = Math.round(receivedChunks / t.totalChunks * 100);
1750	        saveFileMessage(t.uuid, fileMsg);
1751	        if (currentChat === t.uuid) renderMessages(t.uuid);
1752	    }
1753	
1754	    // 6. 重新发送 file_request（带 resume 标记，接收方会跳过确认直接接受）
1755	    const fileRequestMsg = {
1756	        transfer_id: transferId,
1757	        file_name: t.file.name,
1758	        file_size: t.file.size,
1759	        chunk_size: t.CHUNK_SIZE,
1760	        total_chunks: t.totalChunks,
1761	        resume: true,
1762	    };
1763	
1764	    const ws = activeChats.get(t.uuid);
1765	    if (ws && ws.readyState === WebSocket.OPEN) {
1766	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
1767	    } else {
1768	        // 回退路径：通过 control WS 转发
1769	        controlWs.send(JSON.stringify({
1770	            type: 'file_request',
1771	            to_uuid: t.uuid,
1772	            ...fileRequestMsg,
1773	        }));
1774	    }
1775	}
