1777	function readAsBase64(blob) {
1778	    return new Promise((resolve) => {
1779	        const reader = new FileReader();
1780	        reader.onloadend = () => {
1781	            const result = reader.result;
1782	            // 去掉 "data:...;base64," 前缀
1783	            const b64 = result.split(',')[1] || result;
1784	            resolve(b64);
1785	        };
1786	        reader.readAsDataURL(blob);
1787	    });
1788	}
