1861	/** 根据 transfer_id 在所有联系人的消息中查找文件消息 */
1862	function findFileMsgByTransferId(transferId) {
1863	    for (const [uuid, contact] of contacts) {
1864	        if (contact.messages) {
1865	            // 从后往前找（文件消息通常在末尾）
1866	            for (let i = contact.messages.length - 1; i >= 0; i--) {
1867	                if (contact.messages[i].transfer_id === transferId) {
1868	                    return contact.messages[i];
1869	                }
1870	            }
1871	        }
1872	    }
1873	    return null;
1874	}
