1876	/** 持久化文件消息到后端 contacts.json（里程碑状态变化时调用，避免每次进度更新都写盘） */
1877	function saveFileMessage(peerUuid, fileMsg) {
1878	    if (!peerUuid || !fileMsg || !fileMsg.msg_id) return;
1879	    controlWs.send(JSON.stringify({
1880	        type: 'save_message',
1881	        msg_type: 'file',
1882	        peer_uuid: peerUuid,
1883	        sender: fileMsg.from === 'me' ? 'me' : peerUuid,
1884	        content: '',
1885	        msg_id: fileMsg.msg_id,
1886	        file_name: fileMsg.file_name,
1887	        file_size: fileMsg.file_size,
1888	        transfer_id: fileMsg.transfer_id,
1889	        status: fileMsg.status,
1890	        progress: fileMsg.progress || 0,
1891	    }));
1892	}
